import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.concurrent.ThreadLocalRandom;

public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            long val = 0;
            while (b >= '0' && b <= '9') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -val : val;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    static int lowerBound(long[] vals, int[] idxs, long V, int targetIdx) {
        int l = 0, r = vals.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (vals[mid] < V || (vals[mid] == V && idxs[mid] < targetIdx)) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }

    static int count(long[] vals, int[] idxs, long V, int low, int high) {
        if (low > high) return 0;
        int first = lowerBound(vals, idxs, V, low);
        int last = lowerBound(vals, idxs, V, high + 1);
        return last - first;
    }

    static void sort(long[] val, int[] idx, int l, int r) {
        if (l >= r) return;
        int pIdx = ThreadLocalRandom.current().nextInt(r - l + 1) + l;
        long pVal = val[pIdx];
        int pI = idx[pIdx];

        int i = l, j = r;
        while (i <= j) {
            while (val[i] < pVal || (val[i] == pVal && idx[i] < pI)) i++;
            while (val[j] > pVal || (val[j] == pVal && idx[j] > pI)) j--;
            if (i <= j) {
                long tv = val[i]; val[i] = val[j]; val[j] = tv;
                int ti = idx[i]; idx[i] = idx[j]; idx[j] = ti;
                i++;
                j--;
            }
        }
        sort(val, idx, l, j);
        sort(val, idx, i, r);
    }

    static int[] parent;
    static int[] left;
    static int[] right;
    static boolean[] active;

    static int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }

    static void union(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);
        if (rootU != rootV) {
            parent[rootV] = rootU;
            left[rootU] = Math.min(left[rootU], left[rootV]);
            right[rootU] = Math.max(right[rootU], right[rootV]);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int q = scanner.nextInt();
        long k = scanner.nextLong();

        long[] a = new long[n + 1];
        long[] x = new long[n + 1];
        long[] y = new long[n + 1];

        long[] sortedX = new long[n];
        int[] sortedIdxX = new int[n];
        long[] sortedY = new long[n];
        int[] sortedIdxY = new int[n];

        for (int i = 1; i <= n; i++) {
            a[i] = scanner.nextLong();
            x[i] = (long) i + a[i];
            y[i] = (long) i - a[i];
            sortedX[i - 1] = x[i];
            sortedIdxX[i - 1] = i;
            sortedY[i - 1] = y[i];
            sortedIdxY[i - 1] = i;
        }

        sort(sortedX, sortedIdxX, 0, n - 1);
        sort(sortedY, sortedIdxY, 0, n - 1);

        int[] d = new int[n + 1];
        boolean[] inD = new boolean[n + 1];
        for (int i = 1; i <= q; i++) {
            d[i] = scanner.nextInt();
            inD[d[i]] = true;
        }

        int cur = q + 1;
        for (int i = 1; i <= n; i++) {
            if (!inD[i]) {
                d[cur++] = i;
            }
        }

        parent = new int[n + 2];
        left = new int[n + 2];
        right = new int[n + 2];
        active = new boolean[n + 2];

        long[] ans = new long[q + 1];
        long currentAns = 0;

        for (int t = n; t >= 1; t--) {
            int p = d[t];

            int lBound = p;
            int rBound = p;

            if (p - 1 >= 1 && active[p - 1]) {
                lBound = left[find(p - 1)];
            }
            if (p + 1 <= n && active[p + 1]) {
                rBound = right[find(p + 1)];
            }

            int lenL = p - lBound;
            int lenR = rBound - p;

            long added = 0;

            if (lenL <= lenR) {
                for (int i = lBound; i <= p; i++) {
                    int jMin = (i < p) ? p : p + 1;
                    if (jMin > rBound) continue;

                    long maxJ1 = Math.min((long) rBound, (long) i + k);
                    if (jMin <= maxJ1) {
                        added += count(sortedX, sortedIdxX, x[i] + k, jMin, (int) maxJ1);
                    }

                    long maxJ2 = Math.min((long) rBound, (long) i + k - 1);
                    if (jMin <= maxJ2) {
                        added += count(sortedY, sortedIdxY, y[i] + k, jMin, (int) maxJ2);
                    }
                }
            } else {
                for (int j = p; j <= rBound; j++) {
                    int iMax = (j > p) ? p : p - 1;
                    if (lBound > iMax) continue;

                    long minI1 = Math.max((long) lBound, (long) j - k);
                    if (minI1 <= iMax) {
                        added += count(sortedX, sortedIdxX, x[j] - k, (int) minI1, iMax);
                    }

                    long minI2 = Math.max((long) lBound, (long) j - k + 1);
                    if (minI2 <= iMax) {
                        added += count(sortedY, sortedIdxY, y[j] - k, (int) minI2, iMax);
                    }
                }
            }

            currentAns += added;

            active[p] = true;
            left[p] = p;
            right[p] = p;
            parent[p] = p;

            if (p - 1 >= 1 && active[p - 1]) {
                union(p, p - 1);
            }
            if (p + 1 <= n && active[p + 1]) {
                union(p, p + 1);
            }

            if (t - 1 <= q) {
                ans[t - 1] = currentAns;
            }
        }

        for (int i = 0; i <= q; i++) {
            out.println(ans[i]);
        }

        out.flush();
    }
}
